entries[402832] = { ["name"] = "Prayer of Mending", ["text"] = "Gain the Prayer of Mending ability:\n\nPlaces a spell on the target that heals them for [(172 + (Healing * 0.42899999 )) * ( 1 * 1 )] the next time they take damage or receive non-periodic healing. When the heal occurs, Prayer of Mending jumps to a party or raid member within 20 yards. Jumps up to 5 times and lasts 30 sec after each jump. This spell can only be placed on one target at a time per caster." }
entries[402833] = { ["name"] = "Shadow Word: Death", ["text"] = "Gain the Shadow Word: Death ability:\n\nA word of dark binding that inflicts [source value] to [source value] Shadow damage to the target. If the target is not killed by Shadow Word: Death, the caster takes damage equal to 50% of the damage attempted against the target.", ["unresolvedValues"] = true }
