entries[403789] = { ["name"] = "Metamorphosis", ["text"] = "100% of base mana\nInstant\nTransform into a Demon, increasing Armor by 500%, Health by 15%, reducing the chance you will be critically hit by 6%, increasing your threat by 77%, increasing mana gained from Life Tap by 100%, but reducing all damage you deal by 15%. Metamorphosis transforms the functionality of some abilities and grants new ones:\n\nSearing Pain: Now instant.\n\nShadow Bolt: Becomes Shadow Cleave, a Shadow melee attack that hits up to 10 nearby enemies, but has a 6 sec cooldown.\n\nFear: Replaced with Menace.\n\nTaunts the target to attack you, but has no effect if the target is already attacking you.\n\nDemon Charge\n\nCharge an enemy and stun it for 1 sec. Cannot be used in combat.\n\nDemonic Howl\n\nForces all nearby enemies to focus attacks on you for 6 sec." }
entries[403816] = { ["name"] = "Metamorphosis", ["text"] = "Transform into a Demon, increasing Armor by 500%, reducing the chance you will be critically hit by 6%, increasing your threat by 77%, increasing mana gained from Life Tap by 100%, and transforming the functionality of some of your abilities:\n\nSearing Pain: Now instant.\n\nShadow Bolt: Becomes Shadow Cleave, a Shadow melee attack that hits up to 500 nearby enemies.\n\nCurse of Recklessness: Now also taunts your target to attack you for until canceled.\n\nHowl of Terror: Now also forces all nearby enemies to attack you for until canceled, but cooldown increased to 10 minutes." }
entries[403828] = { ["name"] = "Menace", ["text"] = "Melee Range\nInstant 10 sec cooldown\nTaunts the target to attack you, but has no effect if the target is already attacking you." }
entries[403835] = { ["name"] = "Shadow Cleave", ["text"] = "12 Mana Melee Range\nInstant 6 sec cooldown\nPunish up to 10 nearby enemies with a Shadow lash, dealing 3 to 6 to each.\n\nShadow Cleave benefits from and triggers most talents and effects that Shadow Bolt benefits from and triggers. [ S03 - Tuning and Overrides Passive - All Classes : Hitting a target with Shadow Cleave also grants you 4 Spell Damage for each point of your defense skill beyond ( 5 * 5). Lasts 15 sec ]" }
