entries[403873] = { ["name"] = "Metamorphosis", ["text"] = "Gain the Metamorphosis ability:\n\nTransform into a Demon, increasing Armor by 500%, Health by 15%, reducing the chance you will be critically hit by 6%, increasing your threat by 77%, increasing mana gained from Life Tap by 100%, but reducing all damage you deal by 15%. Metamorphosis transforms the functionality of some abilities and grants new ones:\n\nSearing Pain: Now instant.\n\nShadow Bolt: Becomes Shadow Cleave, a Shadow melee attack that hits up to 10 nearby enemies, but has a 6 sec cooldown.\n\nFear: Replaced with Menace.\n\nTaunts the target to attack you, but has no effect if the target is already attacking you.\n\nDemon Charge\n\nCharge an enemy and stun it for 1 sec. Cannot be used in combat.\n\nDemonic Howl\n\nForces all nearby enemies to focus attacks on you for 6 sec." }
entries[403919] = { ["name"] = "Engrave Gloves - Haunt", ["text"] = "3 sec cast\nRequires Gloves\nEngrave your gloves with the Haunt rune:\n\nSend a ghostly soul to assault your current target, dealing 115 to 135 damage, and increasing all Shadow damage over time you deal to that target by 10% for 12 sec. When Haunt expires for any reason you will be healed for 100% of the damage it dealt to your target." }
entries[403920] = { ["name"] = "Engrave Cloak - Soul Siphon", ["text"] = "3 sec cast\nRequires Cloak\nEngrave your cloak with the Soul Siphon rune:\n\nIncreases health drained or damage done by your Drain Life, Drain Soul, and Wrack spells by 20%." }
entries[403925] = { ["name"] = "Engrave Gloves - Chaos Bolt", ["text"] = "3 sec cast\nRequires Gloves\nEngrave your gloves with the Chaos Bolt rune:\n\nSends a bolt of chaotic fire at the enemy, dealing [source value] to [source value] Chaos damage. Chaos Bolt always hits, cannot be resisted, and its knowledge causes all your Fire spells to pierce through absorption effects. Chaos Bolt gains a high chance to be resisted when used against monsters 4 or more levels above your level.", ["unresolvedValues"] = true }
entries[403932] = { ["name"] = "Engrave Chest - Master Channeler", ["text"] = "3 sec cast\nRequires Chest, Chest\nEngrave your chest or robe with the Master Channeler rune:\n\nYour Drain Life is no longer channeled, lasts 15 sec with a 15 sec cooldown, costs 100% more mana, and heals you for 50% more each time it deals damage." }
